package com.gerenciadorrural.infrastructure.database;
import org.junit.jupiter.api.Test; import java.sql.*; import static org.assertj.core.api.Assertions.assertThat;
class InventoryMigrationTest extends PostgresMigrationTestSupport {
 @Test void createsTheInventoryProjectionAndAppendOnlyLedgerWithRls() throws Exception {try(Connection c=adminConnection();Statement s=c.createStatement()){for(String table:new String[]{"inventory_products","inventory_locations","inventory_balances","inventory_operations","inventory_movements"})try(ResultSet r=s.executeQuery("select relrowsecurity,relforcerowsecurity from pg_class join pg_namespace on pg_namespace.oid=relnamespace where nspname='app' and relname='"+table+"'")){assertThat(r.next()).isTrue();assertThat(r.getBoolean(1)).isTrue();assertThat(r.getBoolean(2)).isTrue();}try(ResultSet r=s.executeQuery("select has_table_privilege('public','app.inventory_movements','update,delete,truncate'),has_table_privilege('app_api','app.inventory_movements','select,insert')")){assertThat(r.next()).isTrue();assertThat(r.getBoolean(1)).isFalse();assertThat(r.getBoolean(2)).isTrue();}}}
 @Test void constrainsMovementShapeAndNonNegativeBalances() throws Exception {try(Connection c=adminConnection();Statement s=c.createStatement()){assertThat(org.assertj.core.api.Assertions.catchThrowable(()->s.execute("insert into app.inventory_balances(tenant_id,farm_id,location_id,product_id,quantity) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),-1)"))).isInstanceOf(SQLException.class);}}
}
